package com.ibs;
import java.time.Instant;
import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
@RestController
@RequestMapping("/api/support/tickets")
public class ServiceDeskController {
 private final Map<String,Map<String,Object>> tickets=new LinkedHashMap<>();
 private int sequence=1000;
 private void auth(HttpServletRequest r){if(!SupportPortalController.authorized(r))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);}
 private String value(Map<String,String> b,String k,int max){String s=b.getOrDefault(k,"");if(s==null||s.length()>max)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,k);return s.trim();}
 @GetMapping public synchronized List<Map<String,Object>> list(HttpServletRequest r){auth(r);return tickets.values().stream().map(x->new LinkedHashMap<String,Object>(x)).map(x->(Map<String,Object>)x).toList();}
 @PostMapping public synchronized Map<String,Object> create(HttpServletRequest r,@RequestBody Map<String,String> b){auth(r);if(tickets.size()>=500)throw new ResponseStatusException(HttpStatus.CONFLICT,"Training capacity reached");String app=value(b,"application",10);if(!Set.of("IBS","EIMP").contains(app))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);String title=value(b,"title",200),p=value(b,"priority",2);if(title.isBlank()||!Set.of("P1","P2","P3","P4").contains(p))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);Instant now=Instant.now();long hours=switch(p){case "P1"->4;case "P2"->8;case "P3"->24;default->72;};Map<String,Object> t=new LinkedHashMap<>();String id=String.format("INC%07d",++sequence);t.put("id",id);t.put("application",app);t.put("title",title);t.put("priority",p);t.put("description",value(b,"description",4000));t.put("requestId",value(b,"requestId",128));t.put("state","New");t.put("group","L1 Support");t.put("assignee","");t.put("created",now.toString());t.put("deadline",now.plusSeconds(hours*3600).toString());t.put("rca","");t.put("resolution","");t.put("notes",List.of());tickets.put(id,t);return new LinkedHashMap<>(t);}
 @PutMapping("/{id}") public synchronized Map<String,Object> update(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,String> b){auth(r);Map<String,Object> t=tickets.get(id);if(t==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);String state=value(b,"state",30),group=value(b,"group",60),assignee=value(b,"assignee",100),rca=value(b,"rca",4000),resolution=value(b,"resolution",4000),note=value(b,"note",2000);String old=t.get("state").toString();if(!Set.of("New","In Progress","On Hold","Resolved","Closed").contains(state)||old.equals("Closed")||state.equals("Closed")&&!old.equals("Resolved")||Set.of("Resolved","Closed").contains(state)&&(rca.isBlank()||resolution.isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid state or missing RCA/resolution");List<Object> notes=new ArrayList<>((List<?>)t.get("notes"));if(notes.size()>=200)throw new ResponseStatusException(HttpStatus.CONFLICT,"History limit");notes.add(Map.of("time",Instant.now().toString(),"text",old+" → "+state+" | "+group+" | "+assignee+" | "+note));t.put("notes",List.copyOf(notes));t.put("state",state);t.put("group",group);t.put("assignee",assignee);t.put("rca",rca);t.put("resolution",resolution);if(state.equals("Resolved")&&!old.equals("Resolved"))t.put("resolved",Instant.now().toString());if(!Set.of("Resolved","Closed").contains(state))t.remove("resolved");return new LinkedHashMap<>(t);}
}
